CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_state AS ENUM ('active','suspended','deleted');
CREATE TYPE contact_state AS ENUM ('pending','accepted','blocked','removed');
CREATE TYPE message_state AS ENUM ('sent','delivered','read');
CREATE TYPE session_state AS ENUM ('active','revoked','expired');
CREATE TYPE outbox_state AS ENUM ('pending','processing','done','dead');
CREATE TABLE app_user (user_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username varchar(32) NOT NULL, username_norm varchar(32) NOT NULL UNIQUE, display_name varchar(80) NOT NULL, password_hash varchar(255), phone_e164 varchar(20) UNIQUE, state user_state NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz, CONSTRAINT user_name_ck CHECK (username ~ '^[A-Za-z0-9_.-]{3,32}$'), CONSTRAINT user_display_ck CHECK (length(btrim(display_name)) BETWEEN 1 AND 80));
CREATE TABLE contact_list (owner_user_id uuid NOT NULL REFERENCES app_user(user_id) ON DELETE CASCADE, contact_user_id uuid NOT NULL REFERENCES app_user(user_id) ON DELETE CASCADE, state contact_state NOT NULL DEFAULT 'pending', alias varchar(80), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_user_id,contact_user_id), CONSTRAINT contact_self_ck CHECK(owner_user_id <> contact_user_id));
CREATE INDEX contact_owner_idx ON contact_list(owner_user_id,state,updated_at DESC);
CREATE TABLE user_session (session_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_user(user_id) ON DELETE CASCADE, token_hash bytea NOT NULL UNIQUE, client_type varchar(12) NOT NULL, device_label varchar(80), issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, last_used_at timestamptz, revoked_at timestamptz, state session_state NOT NULL DEFAULT 'active', CONSTRAINT session_type_ck CHECK(client_type IN ('android','j2me','web','service')), CONSTRAINT session_expiry_ck CHECK(expires_at > issued_at), CONSTRAINT token_hash_ck CHECK(octet_length(token_hash)=32));
CREATE TABLE message (message_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_user_id uuid NOT NULL REFERENCES app_user(user_id), recipient_user_id uuid NOT NULL REFERENCES app_user(user_id), client_message_id varchar(64) NOT NULL, sequence_no bigint GENERATED ALWAYS AS IDENTITY UNIQUE, body text NOT NULL, status message_state NOT NULL DEFAULT 'sent', created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, read_at timestamptz, CONSTRAINT message_sender_client_uq UNIQUE(sender_user_id,client_message_id), CONSTRAINT message_party_ck CHECK(sender_user_id <> recipient_user_id), CONSTRAINT message_body_ck CHECK(length(body) BETWEEN 1 AND 4096));
CREATE INDEX message_recipient_cursor_idx ON message(recipient_user_id,sequence_no);
CREATE INDEX message_conversation_idx ON message(LEAST(sender_user_id,recipient_user_id),GREATEST(sender_user_id,recipient_user_id),sequence_no);
CREATE TABLE message_receipt (message_id uuid NOT NULL REFERENCES message(message_id) ON DELETE CASCADE, recipient_user_id uuid NOT NULL REFERENCES app_user(user_id) ON DELETE CASCADE, delivered_at timestamptz, read_at timestamptz, PRIMARY KEY(message_id,recipient_user_id), CONSTRAINT receipt_order_ck CHECK(read_at IS NULL OR delivered_at IS NOT NULL));
CREATE TABLE message_outbox (outbox_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, message_id uuid NOT NULL REFERENCES message(message_id) ON DELETE CASCADE, event_type varchar(32) NOT NULL, state outbox_state NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, last_error_code varchar(64), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_id,event_type));
CREATE INDEX outbox_work_idx ON message_outbox(state,available_at,outbox_id);
